 d['key_results'][0]['en']={13:'Reported accuracy 97.3%; update 48 to 2.3 hours; warning lead time 24 to 72 hours; maintenance cost efficiency +31.2%.',14:'Six homes, 50 diary entries, 34 automation-creation entries and one energy-overload warning.',17:'Calibration NMBE 2.91%, CV-RMSE 0.139, R² 0.972; modeling 48 minutes; simulated ASHP energy cost −44.16%.'}[n]
 (O/f'article-{n:02}.json').write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf8')
 print('saved',n,len(d['figures']),len(d['tables']))
